import type { BoardDescription } from './boardCode';

export const selectionKinds = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;

export type Selection =
  | { readonly kind: typeof selectionKinds.closed }
  | { readonly kind: typeof selectionKinds.one; readonly index: number }
  | {
      readonly kind: typeof selectionKinds.mismatch;
      readonly first: number;
      readonly second: number;
      readonly remainingMs: number;
    };

export interface GameState {
  readonly board: BoardDescription;
  readonly deck: readonly number[];
  readonly matched: readonly number[];
  readonly selection: Selection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.deck.length;
}

export function isCardRevealed(state: GameState, index: number): boolean {
  if (state.matched.includes(index)) return true;
  switch (state.selection.kind) {
    case selectionKinds.closed: return false;
    case selectionKinds.one: return state.selection.index === index;
    case selectionKinds.mismatch:
      return state.selection.first === index || state.selection.second === index;
  }
}
import { parseBoardCode } from './boardCode';
import { generateDeck } from './generation';
import { isWon, selectionKinds } from './state';
import type { GameState } from './state';

export const MISMATCH_MS = 800;
export const MAX_MOVES = 999999;
export const MAX_ELAPSED_MS = 359999999;

export function createGame(boardCode: string): GameState {
  const board = parseBoardCode(boardCode);
  if (!board) throw new Error('Invalid board code.');
  return {
    board, deck: generateDeck(board), matched: [],
    selection: { kind: selectionKinds.closed }, moves: 0, elapsedMs: 0, started: false,
  };
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isInteger(index) || index < 0 || index >= state.deck.length
    || state.matched.includes(index) || isWon(state)) return state;
  switch (state.selection.kind) {
    case selectionKinds.closed:
      return { ...state, started: true, selection: { kind: selectionKinds.one, index } };
    case selectionKinds.one: {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.deck[first] === state.deck[index]) {
        return {
          ...state, moves, matched: [...state.matched, first, index],
          selection: { kind: selectionKinds.closed },
        };
      }
      return {
        ...state, moves,
        selection: { kind: selectionKinds.mismatch, first, second: index, remainingMs: MISMATCH_MS },
      };
    }
    case selectionKinds.mismatch:
      return state;
  }
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  if (state.selection.kind !== selectionKinds.mismatch) return { ...state, elapsedMs };
  const remainingMs = state.selection.remainingMs - milliseconds;
  return {
    ...state, elapsedMs,
    selection: remainingMs <= 0
      ? { kind: selectionKinds.closed }
      : { ...state.selection, remainingMs },
  };
}
export const supportedSizes = [4, 6, 8, 10, 12, 14, 16] as const;
export type GridSize = (typeof supportedSizes)[number];
export const MAX_SEED = 2147483646;

export interface BoardDescription {
  readonly code: string;
  readonly size: GridSize;
  readonly seed: number;
}

export function isGridSize(value: unknown): value is GridSize {
  return supportedSizes.some((size) => size === value);
}

export function parseBoardCode(code: string): BoardDescription | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(code);
  if (!match || match[0] !== code) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isGridSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code, size, seed });
}
import type { BoardDescription } from './boardCode';

const MODULUS = 2147483647;
const RESULT_COUNT = MODULUS - 1;

export function nextGeneratorState(state: number): number {
  // The largest product is below 2^53, so these integer operations are exact.
  return (state * 16807) % MODULUS;
}

export function drawBounded(state: number, possibilities: number): readonly [number, number] {
  const limit = Math.floor(RESULT_COUNT / possibilities) * possibilities;
  let next = state;
  do {
    next = nextGeneratorState(next);
  } while (next - 1 >= limit);
  return [next, (next - 1) % possibilities];
}

export function generateDeck(board: BoardDescription): readonly number[] {
  const deck = Array.from({ length: board.size * board.size }, (_, index) => Math.floor(index / 2));
  let randomState = board.seed;
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const [next, destination] = drawBounded(randomState, index + 1);
    randomState = next;
    const first = deck[index];
    const second = deck[destination];
    if (first === undefined || second === undefined) throw new Error('Invalid shuffle index.');
    deck[index] = second;
    deck[destination] = first;
  }
  return Object.freeze(deck);
}
export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  const actual = Object.keys(value);
  return actual.length === keys.length && actual.every((key) => keys.includes(key));
}

export function isUnknownArray(value: unknown): value is readonly unknown[] {
  return Array.isArray(value);
}

export function isNonnegativeInteger(value: unknown): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
}

export function isPosition(value: unknown, length: number): value is number {
  return isNonnegativeInteger(value) && value < length;
}

export function parseLimitedJson(text: string, byteLimit: number): unknown {
  if (new TextEncoder().encode(text).byteLength > byteLimit) return null;
  try {
    const parsed: unknown = JSON.parse(text);
    return parsed;
  } catch {
    return null;
  }
}
export function formatTime(elapsedMs: number): string {
  const seconds = Math.floor(elapsedMs / 1000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}

import { parseBoardCode } from './boardCode';
import { createGame, MAX_ELAPSED_MS, MAX_MOVES } from './game';
import { decodeMatched, decodeSelection } from './snapshotFields';
import { isWon, selectionKinds } from './state';
import type { GameState } from './state';
import { hasExactKeys, isNonnegativeInteger, isRecord, parseLimitedJson } from './validation';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_BYTE_LIMIT = 65536;
const snapshotKeys = ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'];

export function encodeSnapshot(state: GameState): string {
  const selection = state.selection.kind === selectionKinds.mismatch
    ? { ...state.selection, remainingMs: Math.max(1, Math.floor(state.selection.remainingMs)) }
    : state.selection;
  return JSON.stringify({
    version: SNAPSHOT_VERSION, boardCode: state.board.code,
    matched: [...state.matched].sort((first, second) => first - second), selection,
    moves: state.moves, elapsedMs: Math.floor(state.elapsedMs), started: state.started,
  }, null, 2);
}

export function decodeSnapshot(text: string): GameState | null {
  const value = parseLimitedJson(text, SNAPSHOT_BYTE_LIMIT);
  if (!isRecord(value) || !hasExactKeys(value, snapshotKeys)
    || value.version !== SNAPSHOT_VERSION || typeof value.boardCode !== 'string'
    || !parseBoardCode(value.boardCode) || typeof value.started !== 'boolean'
    || !isNonnegativeInteger(value.moves) || value.moves > MAX_MOVES
    || !isNonnegativeInteger(value.elapsedMs) || value.elapsedMs > MAX_ELAPSED_MS) return null;
  const initial = createGame(value.boardCode);
  const matched = decodeMatched(value.matched, initial.deck);
  if (!matched) return null;
  const selection = decodeSelection(value.selection, initial.deck, matched);
  if (!selection) return null;
  const state: GameState = {
    ...initial, matched, selection, moves: value.moves, elapsedMs: value.elapsedMs, started: value.started,
  };
  const pendingMove = selection.kind === selectionKinds.mismatch ? 1 : 0;
  if (state.moves < matched.length / 2 + pendingMove) return null;
  if (isWon(state) && selection.kind !== selectionKinds.closed) return null;
  if (!state.started && (state.moves !== 0 || state.elapsedMs !== 0
    || matched.length !== 0 || selection.kind !== selectionKinds.closed)) return null;
  if (state.started && state.moves === 0 && selection.kind !== selectionKinds.one) return null;
  return state;
}
import { MISMATCH_MS } from './game';
import { selectionKinds } from './state';
import type { Selection } from './state';
import { hasExactKeys, isPosition, isRecord, isUnknownArray } from './validation';

export function decodeMatched(value: unknown, deck: readonly number[]): readonly number[] | null {
  if (!isUnknownArray(value)) return null;
  const matched: number[] = [];
  const faceCounts = new Map<number, number>();
  for (const index of value) {
    if (!isPosition(index, deck.length) || matched.includes(index)) return null;
    const face = deck[index];
    if (face === undefined) return null;
    matched.push(index);
    faceCounts.set(face, (faceCounts.get(face) ?? 0) + 1);
  }
  if ([...faceCounts.values()].some((count) => count !== 2)) return null;
  return matched;
}

export function decodeSelection(
  value: unknown, deck: readonly number[], matched: readonly number[],
): Selection | null {
  if (!isRecord(value)) return null;
  const available = (index: unknown): index is number =>
    isPosition(index, deck.length) && !matched.includes(index);
  switch (value.kind) {
    case selectionKinds.closed:
      return hasExactKeys(value, ['kind']) ? { kind: selectionKinds.closed } : null;
    case selectionKinds.one:
      return hasExactKeys(value, ['kind', 'index']) && available(value.index)
        ? { kind: selectionKinds.one, index: value.index } : null;
    case selectionKinds.mismatch: {
      const { first, second, remainingMs } = value;
      if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs'])
        || !available(first) || !available(second) || first === second
        || deck[first] === deck[second] || typeof remainingMs !== 'number'
        || !Number.isInteger(remainingMs) || remainingMs < 1 || remainingMs > MISMATCH_MS) return null;
      return { kind: selectionKinds.mismatch, first, second, remainingMs };
    }
    default:
      return null;
  }
}
