const shapes = ['circle', 'square', 'triangle', 'diamond', 'star', 'hexagon', 'plus', 'chevron'] as const;
const palette = [
  { name: 'cyan', color: '#63E7FF' }, { name: 'magenta', color: '#FF71D6' },
  { name: 'green', color: '#8BEA7D' }, { name: 'yellow', color: '#FFE082' },
  { name: 'orange', color: '#FFB064' }, { name: 'violet', color: '#B49AFF' },
  { name: 'rose', color: '#FF8296' }, { name: 'ice', color: '#D9F3FF' },
] as const;
const diagonal = 40 / Math.sqrt(2);
const markers = [
  { name: 'top', x: 0, y: -40 }, { name: 'top-right', x: diagonal, y: -diagonal },
  { name: 'right', x: 40, y: 0 }, { name: 'bottom-right', x: diagonal, y: diagonal },
  { name: 'bottom', x: 0, y: 40 }, { name: 'bottom-left', x: -diagonal, y: diagonal },
  { name: 'left', x: -40, y: 0 }, { name: 'top-left', x: -diagonal, y: -diagonal },
] as const;

export type FaceShape = (typeof shapes)[number];
export const fills = { solid: 'solid', outline: 'outline' } as const;

export function describeFace(id: number) {
  if (!Number.isInteger(id) || id < 0 || id > 127) throw new RangeError('Invalid face identity.');
  const shape = shapes[id % 8];
  const markerIndex = Math.floor(id / 8) % 8;
  const marker = markers[markerIndex];
  const color = palette[markerIndex];
  if (!shape || !marker || !color) throw new RangeError('Invalid face identity.');
  const fill = id < 64 ? fills.solid : fills.outline;
  return {
    shape, fill, color: color.color, markerX: 50 + marker.x, markerY: 50 + marker.y,
    name: `${color.name} ${fill} ${shape}, marker ${marker.name}`,
  };
}

export function faceName(id: number): string {
  return describeFace(id).name;
}
import { describeFace, fills } from './faces.ts';
import type { FaceShape } from './faces.ts';

function Shape({ shape }: { readonly shape: FaceShape }) {
  switch (shape) {
    case 'circle': return <circle cx="50" cy="50" r="22.5" />;
    case 'square': return <rect x="27.5" y="27.5" width="45" height="45" />;
    case 'triangle': return <polygon points="50,27.5 72.5,72.5 27.5,72.5" />;
    case 'diamond': return <polygon points="50,27.5 72.5,50 50,72.5 27.5,50" />;
    case 'star': return <polygon points="50,27.5 56.61,40.90 71.40,43.05 60.70,53.48 63.23,68.20 50,61.25 36.77,68.20 39.30,53.48 28.60,43.05 43.39,40.90" />;
    case 'hexagon': return <polygon points="38.75,30.5144 61.25,30.5144 72.5,50 61.25,69.4856 38.75,69.4856 27.5,50" />;
    case 'plus': return <path d="M42 27.5H58V42H72.5V58H58V72.5H42V58H27.5V42H42Z" />;
    case 'chevron': return <polygon points="27.5,27.5 50,27.5 72.5,50 50,72.5 27.5,72.5 50,50" />;
  }
}

export interface FaceSvgProps { readonly faceId: number }

export function FaceSvg({ faceId }: FaceSvgProps) {
  const face = describeFace(faceId);
  const outline = face.fill === fills.outline;
  return (
    <svg className="card-face" viewBox="0 0 100 100" aria-hidden="true" focusable="false">
      <g fill={outline ? 'none' : face.color} stroke={outline ? face.color : 'none'}
        strokeWidth="5" strokeLinejoin="round">
        <Shape shape={face.shape} />
      </g>
      <circle cx={face.markerX} cy={face.markerY} r="5" fill={face.color}
        stroke="#111625" strokeWidth="3" />
    </svg>
  );
}

export function CardBack() {
  return (
    <svg className="card-back" viewBox="0 0 100 100" aria-hidden="true" focusable="false">
      <path d="M50 32 68 50 50 68 32 50Z" fill="none" stroke="#757C9A" strokeWidth="3" />
    </svg>
  );
}
import type { GridSize } from '../boardCode.ts';

export function arrowDestination(index: number, size: GridSize, key: string): number | null {
  switch (key) {
    case 'ArrowLeft': return index % size > 0 ? index - 1 : index;
    case 'ArrowRight': return index % size < size - 1 ? index + 1 : index;
    case 'ArrowUp': return index >= size ? index - size : index;
    case 'ArrowDown': return index < size * (size - 1) ? index + size : index;
    default: return null;
  }
}

